from pathlib import Path
import importlib.util,json,sys,xml.etree.ElementTree as ET
sys.dont_write_bytecode=True
ROOT=Path(__file__).resolve().parent
spec=importlib.util.spec_from_file_location('ronda1',ROOT.parent/'generar.py')
base=importlib.util.module_from_spec(spec);spec.loader.exec_module(base)
contrast=base.contrast
# Contornos propios. Más peso, menor tracking, punto circular y K de hombro curvo.
base.GLYPHS['K']=(55,'M2 0H12V31L37 2Q39 0 42 0H54L25 34L54 72H41L12 38V72H2Q0 72 0 70V2Q0 0 2 0Z')
base.GLYPHS['i']=(14,'M13 6A6 6 0 1 1 1 6A6 6 0 1 1 13 6ZM2 23H12V72H2Z')
P=[
{'id':'01-solaria','name':'Solaria','tag':'ORO / GEMA / SALA DE CINE','idea':'Una corona de tres puntas elásticas, con hombros redondeados y una gema de rombo ancho tallada en negativo. El arco inferior le da el gesto de una joya, sin ornamento pequeño.','shape':'M8 42L4 18Q3 13 7 15L19 24Q22 26 24 22L29 9Q32 2 35 9L40 22Q42 26 45 24L57 15Q61 13 60 18L56 42Q55 46 51 46H13Q9 46 8 42ZM25 34Q24 33 25 32L31 27Q32 26 33 27L39 32Q40 33 39 34L33 39Q32 40 31 39Z','base':'M12 50Q32 54 52 50L51 56Q32 60 13 56Z','palette':['#0d172b','#1d2d49','#fff4e4','#bac8e0','#f2b84b','#fff1d2'],'kids':'#ff9478','track':3,'scale':1.0},
{'id':'02-brasa','name':'Brasa','tag':'CORAL / CORTE / MOVIMIENTO','idea':'Una corona inclinada, con una punta central alta y dos valles de curva continua. Un corte oblicuo atraviesa su lado derecho: una firma dinámica visible incluso en pequeño.','shape':'M9 44L4 20Q3 15 7 18L18 26Q21 28 24 23L31 8Q34 3 36 9L40 22Q41 26 45 24L56 15Q61 12 60 18L57 27L44 42H32L52 45L51 48Q30 53 13 49Q10 48 9 44Z','base':'M15 54Q30 58 48 54L47 59Q31 63 16 59Z','palette':['#101827','#23344e','#fff2e8','#b8c9e5','#ff7a59','#f5d58d'],'kids':'#f6c45a','track':2,'scale':.96},
{'id':'03-aurora','name':'Aurora','tag':'COBRE / PLAY / CORONA','idea':'Una corona baja de tres puntas, curvada como una cinta. Su gema es una ventana de reproducción de esquinas redondeadas: play integrado en la masa, nunca como icono independiente.','shape':'M8 43L4 20Q3 14 8 17L19 24Q22 26 24 22L29 11Q32 5 35 11L40 22Q42 26 45 24L56 17Q61 14 60 20L56 43Q55 48 50 48H14Q9 48 8 43ZM27 29Q27 27 29 28L39 34Q41 35 39 37L29 43Q27 44 27 42Z','base':'M13 52Q32 56 51 52L50 58Q32 62 14 58Z','palette':['#0a1631','#1d3156','#fff5e8','#b6c8e8','#f5a66a','#b9d8ff'],'kids':'#ffd16f','track':4,'scale':1.04}]
TOKENS=base.TOKENS

def symbol(p):
    return base.svg('Corona Kingdom · '+p['name'],'0 0 64 64',f'<path fill="{p["palette"][4]}" fill-rule="evenodd" d="{p["shape"]}"/><path fill="{p["palette"][2]}" d="{p["base"]}"/>')
def wordmark(p,player=False):
    paths,w=base.letters('Kingdom',p['track']);w*=p['scale']
    body=f'<g transform="translate(2 5) scale({p["scale"]} 1)" fill="{p["palette"][2]}" stroke="{p["palette"][2]}" stroke-width="2.2" stroke-linejoin="round" fill-rule="evenodd">{paths}</g>'
    if player:
        paths,pw=base.letters('Player',3)
        body+=f'<g transform="translate({w+25} 42) scale(.52)" fill="{p["palette"][4]}" stroke="{p["palette"][4]}" stroke-width="1.6" stroke-linejoin="round" fill-rule="evenodd">{paths}</g>'
        w+=25+pw*.52
    return base.svg('Kingdom Player' if player else 'Kingdom',f'0 0 {w+5:g} 104',body)
def measures(p):
    bg,surface,text,secondary,accent,focus=p['palette']
    return {'texto / fondo':contrast(text,bg),'texto secundario / fondo':contrast(secondary,bg),'acento / fondo':contrast(accent,bg),'foco / fondo':contrast(focus,bg),'texto / superficie':contrast(text,surface),'texto secundario / superficie':contrast(secondary,surface),'foco / superficie':contrast(focus,surface),'tinta fondo / botón acento':contrast(bg,accent),'Kids / fondo':contrast(p['kids'],bg),'tinta fondo / botón Kids':contrast(bg,p['kids']),'superficie / fondo':contrast(surface,bg)}
def assets(p):
    folder=ROOT/p['id'];folder.mkdir(exist_ok=True)
    for filename,content in [('simbolo.svg',symbol(p)),('kingdom.svg',wordmark(p)),('kingdom-player.svg',wordmark(p,True))]:
        (folder/filename).write_text(content+'\n',encoding='utf-8')
    data={'propuesta':p['name'],'tokens':dict(zip(TOKENS,p['palette'])),'kids-acento':p['kids'],'contrastes':{k:round(v,4) for k,v in measures(p).items()},'criterio':'Texto normal ≥4.5:1; foco/componentes ≥3:1. Superficie decorativa no requiere 3:1 respecto al fondo; no usarla como único indicador de foco.'}
    (folder/'paleta.json').write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    (folder/'README.md').write_text(f'''# {p['name']} · ronda 2

{p['idea']}

Acento {p['palette'][4]}, fondo azul noche {p['palette'][0]}, foco {p['palette'][5]}, Kids {p['kids']}. Superficie elevada oscura {p['palette'][1]}, con texto claro. Kids mantiene el mismo foco. El botón cálido usa tinta del token fondo.

`simbolo.svg`: corona original sin texto, trazados de curvas cuadráticas y recortes anchos, cuadrícula de 64 unidades. `kingdom.svg`: lettering geométrico propio reforzado, K con hombro curvo y punto circular; no depende de fuentes. `kingdom-player.svg`: reservado para metadatos. No alterar el espaciado ni añadir detalles. Los recortes grandes y banda neutra permanecen en las tres escalas. Sobre arte usar placa del token fondo y margen mínimo de 8 unidades; a 16 px el reconocimiento depende de la silueta y del vacío principal.

Paleta y contrastes numéricos en `paleta.json`. Texto principal/secundario AA sobre fondo y superficie; acento/Kids AA sobre fondo; foco supera 3:1 sobre ambos soportes. Separar el halo del arte con 6 px oscuros. Las muestras del póster emplean placa oscura: los colores del contenido son arbitrarios.

Los títulos y controles mantienen Bricolage Grotesque/Manrope en G2. Esta propuesta no modifica la aplicación, ni exporta bitmaps, ni depende de recursos externos.
''',encoding='utf-8')
CSS='''*{box-sizing:border-box}body{margin:0;background:#080f20;color:#fff2e8;font:16px/1.6 system-ui,sans-serif}header,main,footer{max-width:1480px;margin:auto;padding:40px}header{padding-top:64px}h1{font-size:clamp(40px,5vw,68px);line-height:1.05;margin:12px 0 20px;letter-spacing:-2px}h2{font-size:42px;line-height:1.1;margin:12px 0}h3{font-size:19px;margin:30px 0 14px}p{max-width:820px}.eyebrow{font-size:12px;letter-spacing:.2em;color:#f2b84b}a{color:#ffd16f}header nav{display:flex;gap:26px;flex-wrap:wrap}article{padding:30px;background:var(--bg);color:var(--text);border:1px solid #344969;border-radius:24px;margin:0 0 52px;overflow:hidden}.intro{display:flex;gap:26px;align-items:center}.intro-mark{width:88px;height:88px;flex-shrink:0}.intro p{color:var(--secondary)}.intro .eyebrow{color:var(--accent)}svg{display:block;width:100%;height:100%}.note{font-size:14px;color:var(--secondary,#b8c9e5)}.viewport{overflow-x:auto;border:1px solid #405778;border-radius:18px}.app{width:1920px;background:var(--bg)}.topbar{height:112px;display:flex;align-items:center;padding:0 76.8px;gap:45px;background:var(--bg)}.brand{display:flex;align-items:center;gap:12px;flex-shrink:0}.brand-symbol{width:52px;height:52px}.brand-word{width:210px;height:65px}.topbar nav{display:flex;align-items:center;gap:14px}.topbar nav span{padding:14px 15px;font-size:22px;white-space:nowrap;color:var(--secondary);border-radius:28px}.topbar nav .active{background:var(--surface);color:var(--text);font-weight:700;box-shadow:inset 0 -3px var(--accent)}.tools{margin-left:auto;display:flex;gap:24px;align-items:center;color:var(--secondary);font-size:21px}.avatar{width:46px;height:46px;border-radius:16px;background:var(--accent);color:var(--bg);display:grid;place-items:center;font-weight:800}.hero{height:410px;margin:0 57.6px;border-radius:32px;overflow:hidden;position:relative;background:linear-gradient(90deg,var(--bg) 0%,#152d4a 45%,#554654 70%,#dc9060 100%)}.hero:after{content:'';position:absolute;right:185px;top:25px;width:300px;height:300px;border-radius:50%;background:linear-gradient(160deg,#ffe0a366,#f1a16d11);box-shadow:0 0 90px #ffad6a33}.hero-copy{position:relative;z-index:1;padding:48px 76px;max-width:840px}.hero h4{font-size:60px;line-height:1.04;letter-spacing:-2px;margin:8px 0 20px}.hero p{margin:0 0 26px;color:var(--secondary);font-size:24px}.hero .eyebrow{color:var(--accent);font-size:16px}.play{display:inline-flex;gap:12px;align-items:center;border:0;border-radius:32px;background:var(--accent);color:var(--bg);padding:17px 28px;font:800 24px system-ui;cursor:pointer}.play:focus-visible{outline:4px solid var(--focus);outline-offset:6px}.play svg{width:24px;height:24px}.library{padding:26px 76.8px 44px}.library h4{font-size:32px;margin:0 0 18px}.cards{display:flex;gap:22px;padding:12px 8px}.card{width:414px;flex-shrink:0}.poster-card{height:226px;border-radius:20px;position:relative;overflow:hidden;background:linear-gradient(140deg,#264966,#d28f56)}.poster-card:before{content:'';position:absolute;right:30px;top:14px;width:170px;height:170px;border-radius:50%;background:#fff1d225}.poster-card:after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,#101827ed,transparent 85%)}.card:nth-child(2) .poster-card{background:linear-gradient(145deg,#263f6d,#ca7869)}.card:nth-child(3) .poster-card{background:linear-gradient(145deg,#29525a,#cab76c)}.card:nth-child(4) .poster-card{background:linear-gradient(145deg,#5b325b,#e5a16b)}.poster-title{position:absolute;z-index:1;bottom:24px;left:24px;font-size:30px;font-weight:800;letter-spacing:-1px;color:#fff5e8}.card.focused .poster-card{outline:4px solid var(--focus);outline-offset:6px;box-shadow:0 0 0 6px var(--bg),0 0 28px color-mix(in srgb,var(--focus) 32%,transparent)}.caption{font-size:21px;color:var(--secondary);margin:12px 0 0}.focus-label{color:var(--focus);font-size:16px}.sizes{display:grid;grid-template-columns:1fr 1fr;gap:22px}.stage{min-height:665px;border:1px solid #405778;border-radius:16px;display:flex;gap:26px;flex-wrap:wrap;align-items:center;padding:24px;overflow-x:auto;background:var(--bg)}.poster-stage{background:linear-gradient(145deg,#e7a163,#886778 40%,#234460 75%,#101827)}figure{margin:0;flex-shrink:0}.sample{background:var(--bg)}.poster-stage .sample{outline:8px solid var(--bg);border-radius:8px}figcaption{margin-top:12px;background:var(--bg);color:var(--secondary);font-size:13px;width:max-content;padding:3px 7px}.bottom{display:grid;grid-template-columns:1fr 1fr;gap:30px}.word-preview{max-width:500px;height:120px;display:flex;align-items:center}.word-preview svg{height:auto}.tokens{display:flex;gap:8px;flex-wrap:wrap}.chip{padding:14px;border-radius:12px;min-width:95px}.chip strong{display:block;font-size:13px}.chip code{font-size:12px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:10px 6px;border-bottom:1px solid #405778}th{font-weight:500}.swatch{width:18px;height:18px;display:inline-block;margin-right:7px;vertical-align:middle;border-radius:5px;border:1px solid #7790b0}.kids-example{display:inline-block;background:var(--kids);color:var(--bg);padding:13px 24px;border-radius:26px;font-weight:800}.focus-example{display:inline-block;background:var(--surface);color:var(--text);padding:12px 24px;margin-left:24px;border-radius:20px;outline:3px solid var(--focus);outline-offset:5px}@media(max-width:1100px){.sizes,.bottom{grid-template-columns:1fr}}@media(max-width:600px){header,main,footer{padding:20px}article{padding:18px}.intro{display:block}table{font-size:12px}.stage{padding:18px}}'''
def page():
    articles=[]
    for p in P:
        bg,surface,text,secondary,accent,focus=p['palette']
        style=';'.join(f'--{k}:{v}' for k,v in zip(['bg','surface','text','secondary','accent','focus'],p['palette']))+f';--kids:{p["kids"]}'
        menu=''.join(f'<span class="{"active" if n=="Inicio" else ""}">{n}</span>' for n in ['Inicio','Películas','Series','TV en vivo','MLB','Mi lista'])
        cards=''.join(f'<div class="card {"focused" if i==1 else ""}"><div class="poster-card"><span class="poster-title">{title}</span></div><p class="caption">{title} · Película</p>{"<span class=focus-label>Foco del mando</span>" if i==1 else ""}</div>' for i,title in enumerate(['El último verano','Órbita nocturna','El jardín secreto','Después del sol']))
        sizes=[]
        for poster in (False,True):
            samples=''.join(f'<figure><div class="sample" style="width:{s}px;height:{s}px">{symbol(p)}</div><figcaption>{s} × {s} px</figcaption></figure>' for s in (16,48,512))
            sizes.append(f'<div><h3>{"Póster de degradado · placa azul noche" if poster else "Sobre azul noche"}</h3><div class="stage {"poster-stage" if poster else ""}">{samples}</div></div>')
        tokens=''.join(f'<tr><th><span class="swatch" style="background:{c}"></span>{token}</th><td>{c}</td><td>{contrast(c,bg):.2f}:1</td></tr>' for token,c in list(zip(TOKENS,p['palette']))+[('Kids',p['kids'])])
        ratios=''.join(f'<tr><th>{name}</th><td>{ratio:.2f}:1</td><td>{"Decorativa · no aplica" if name=="superficie / fondo" else "AA ✓"}</td></tr>' for name,ratio in measures(p).items())
        articles.append(f'''<article id="{p['id']}" style="{style}"><div class="intro"><div class="intro-mark">{symbol(p)}</div><div><p class="eyebrow">{p['id'][:2]} / {p['tag']}</p><h2>{p['name']}</h2><p>{p['idea']}</p></div></div>
<h3>En la app · lienzo de 1920 px</h3><p class="note">Cabecera basada en la estructura actual: marca a la izquierda, seis secciones, búsqueda y perfil a la derecha; filas y tarjetas redondeadas. Desplaza horizontalmente para ver el lienzo a tamaño real. Arte y títulos de muestra.</p>
<div class="viewport"><div class="app"><div class="topbar"><div class="brand"><div class="brand-symbol">{symbol(p)}</div><div class="brand-word">{wordmark(p)}</div></div><nav aria-label="Menú de muestra {p['name']}">{menu}</nav><div class="tools"><span>⌕ Buscar</span><span class="avatar">R</span></div></div><div class="hero"><div class="hero-copy"><p class="eyebrow">TU SALA DE CINE</p><h4>Historias que<br>se quedan contigo.</h4><p>Una noche, una película, tu propio reino.</p><button type="button" class="play"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M6 3L21 12L6 21Z"/></svg>Reproducir</button></div></div><div class="library"><h4>Para tu próxima noche</h4><div class="cards">{cards}</div></div></div></div>
<div class="sizes">{''.join(sizes)}</div><div class="bottom"><div><h3>Kingdom · lettering geométrico</h3><div class="word-preview">{wordmark(p)}</div><h3>Kingdom Player · solo metadatos</h3><div class="word-preview">{wordmark(p,True)}</div><p class="note">Contornos propios, mayor peso y espaciado compacto. Sin fuentes externas en los logotipos.</p><h3>Kids y superficie elevada</h3><span class="kids-example">Kids</span><span class="focus-example">Foco</span><p class="note">Kids cambia únicamente el acento. La superficie permanece azul y el foco mantiene su color.</p><h3>Los seis tokens + Kids</h3><table><thead><tr><th>Token</th><th>HEX</th><th>Sobre fondo</th></tr></thead><tbody>{tokens}</tbody></table></div><div><h3>Contrastes de uso</h3><table><thead><tr><th>Combinación</th><th>Ratio</th><th>Resultado</th></tr></thead><tbody>{ratios}</tbody></table><p class="note">Texto normal ≥ 4.5:1; halo del mando ≥ 3:1. El fondo contra sí mismo es 1:1. La superficie elevada es decorativa: el foco lo indica su halo, con una separación azul noche de 6 px respecto al póster. Botón Reproducir y Kids llevan tinta azul noche.</p></div></div></article>''')
    page=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kingdom · ronda 2</title><style>{CSS}</style></head><body><header><p class="eyebrow">KINGDOM / G1 / RONDA 02</p><h1>Una corona con carácter.<br>Una sala con calidez.</h1><p>Tres nuevas propuestas: oro con gema, coral con corte y cobre con play integrado. Azul noche profundo, superficies elevadas azules y un acento cálido real. Identidad en contexto de Samsung TV y Electron.</p><nav aria-label="Propuestas"><a href="#01-solaria">01 · Solaria</a><a href="#02-brasa">02 · Brasa</a><a href="#03-aurora">03 · Aurora</a></nav></header><main>{''.join(articles)}</main><footer><p>Comparativa de diseño G1. Esta página usa CSS y SVG inline; no carga imágenes, fuentes ni scripts. Títulos de muestra y degradados originales. Bricolage Grotesque y Manrope permanecen en el producto; la fuente del sistema se usa aquí para textos de contexto.</p><p>Contraste WCAG con sRGB linealizado: canal ≤ 0.04045 → canal/12.92; resto → ((canal+0.055)/1.055)<sup>2.4</sup>. L = 0.2126R + 0.7152G + 0.0722B. Ratio = (L mayor+0.05)/(L menor+0.05). Cumplimiento calculado sin redondear; valores mostrados a dos decimales.</p><p>Las muestras de 512 px conservan su tamaño y admiten desplazamiento en ventanas pequeñas. Sobre póster se utiliza placa azul noche para garantizar contraste. Selección, integración y exportación pertenecen a G2.</p></footer></body></html>'''
    (ROOT/'index.html').write_text(page,encoding='utf-8')
def validate():
    for p in P:
        for f in ('simbolo.svg','kingdom.svg','kingdom-player.svg'):
            tree=ET.parse(ROOT/p['id']/f)
            assert all(e.tag.split('}')[-1] in ('svg','path','g') for e in tree.iter())
        for name,ratio in measures(p).items():
            if name=='superficie / fondo':continue
            assert ratio >= (3 if name.startswith('foco') else 4.5),(p['name'],name,ratio)
        assert p['palette'][4]!=p['palette'][5]
    html=(ROOT/'index.html').read_text(encoding='utf-8')
    assert html.count('<svg ')==36
    assert 'src=' not in html and '<script' not in html
    print('Validación: 9 SVG, 3 coronas curvas, 3 paletas cálidas, AA texto/botones y foco verificados; 36 SVG inline.')
if __name__=='__main__':
    if len(sys.argv)>1 and sys.argv[1] in ('1','2','3'):assets(P[int(sys.argv[1])-1])
    else:page();validate()
